n('lean4/PrimitiveDifference.lean','formal_proof_source','Full 787-line read. PrimitiveDifference assumes reflexive/symmetric/transitive zero relation; quotient and unary/binary factorization iff congruence, uniqueness, product/mod-setoid compatibility and coarsening follow. Bool all-zero/nonconstant delta explicitly refutes automatic factorization. Context fingerprint discards context by definition. Pointed zero and congruence are additional structure. No primitive ontology or runtime checker is derived; quotient results use Quot.sound (some also propext).')
n('lean4/ShadowBoundary.lean','formal_proof_source','Full 1187-line read. Collision witness blocks total decoder; quotient descent iff fiber invariance; refinement, mutually decodable shadows, injective-on-target-image encodings, composition, joint encodings and separating augmentations preserve exact target distinctions. Augmentation separation equivalence assumes DecidableEq Value. Target-augmented success simply includes target and projects snd. Unit/Bool packet, LGGR and zeta worlds are supplied models; generic theorem needs no finiteness hypothesis and provides no detector discovery, approximate-statistical guarantee or physical bridge.')
n('lean4/axiom_report.txt','historical_kernel_run_record','Full 393-line read of Oct27 Linux Lean4.35 census: nine roots, 1144 constants/375 noninternal theorems/281 axiom-free; actual dependencies propext and Quot.sound, while allow-list also permits Classical.choice. Includes generated structure-field/projection lemmas. Historical successful build/census is distinct from source semantic review; parent has independently rerun the same census, not repeated here.')
n('lean4/provenance.json','historical_custody_record','Full 235-line read: source/graded commits, ten file hashes, rehoming decisions, nonmoved files, grade claims and retained-source rationale. All ten current hashes match. Scores/external adversary report not independently regraded; text itself records stale bindings/library-root/path claims. No certification follows from byte identity.')

def h(path): return hashlib.sha256((ROOT/path).read_bytes()).hexdigest()
def ev(path,start,end,kind='source'):
    return {'path':path,'sha256':h(path),'lines':[start,end],'kind':kind}
file_reviews=[]
for row in SCOPE:
    path=row['path']; raw=(ROOT/path).read_bytes(); sha=h(path)
    assert sha==INDEX[path]['sha256'],path
    count=raw.count(b'\n')+int(bool(raw) and not raw.endswith(b'\n'))
    mode='full_text'
    extra={}
    if path.endswith('.contract.score.json'):
        d=json.loads(raw); base='csharp/PfpLab.Client/CoreProcess.contract.score.json' if path.startswith('csharp/') else 'pfp_lab/cli/main.contract.score.json'
        classification='historical_generated_score_record'
        assessment=('Read full baseline and all line replacements, including history, artifact/evidence hashes, gates, invariants and mutation accounting. '+d['score']['level_basis']+' Recorded '+d['score']['score_token']+' is a rubric judgment, not mathematical proof or a current test result. Source/evidence hashes checked separately; historical logs were not reexecuted or semantically reviewed by this receipt.')
        mode='full_baseline_plus_all_lossless_line_differences'
        extra={'baseline_path':base,'baseline_sha256':h(base),'reconstruction_verified':True,'score_token':d['score']['score_token'],'review_helper':'dag/reviews/additional_lab_clients_formal_scores.py'}
    else:
        assert path in notes,path
        classification,assessment=notes[path]
    file_reviews.append({'path':path,'sha256':sha,'full_source_read':True,'assessment':assessment,'classification':classification,'review_mode':mode,'reviewed_lines':[1,count] if count else [],'bytes':len(raw),**extra})
assert len(file_reviews)==102
assert len(notes)==66,len(notes)

